//! Disposable benchmark of existing String numeric conversions.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::size;
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let integer = h.named(b"Integer").unwrap();
    let float = h.named(b"Float").unwrap();
    let gc = h.named(b"GC").unwrap();
    let nil = h.named(b"nil").unwrap();
    q.call(gc, b"automaticCollection:", &[size(0).unwrap()]).unwrap();
    for length in [16, 4096, 1048576] {
        for name in ["integer", "float", "invalid"] {
            let mut bytes = vec![b' '; length];
            let (tail, selector) = match name {
                "integer" => (b"42".as_slice(), b"asInteger".as_slice()),
                "float" => (b"1.25".as_slice(), b"asNumber".as_slice()),
                _ => (b"x".as_slice(), b"asNumber".as_slice()),
            };
            if name == "invalid" { bytes.fill(0xff); }
            bytes[length-tail.len()..].copy_from_slice(tail);
            let source = q.string(&bytes).unwrap();
            let selector = q.keep(h.intern(selector).unwrap()).unwrap();
            let calls = match length { 16 => 20000, 4096 => 2048, _ => 128 };
            for _ in 0..10 { unsafe { h.id.send(source, selector, &[]).unwrap(); } }
            for _ in 0..5 {
                q.call(gc, b"collectPrecisely", &[]).unwrap();
                let mut last = nil;
                let start = unsafe { clock_gettime_nsec_np(16) };
                for _ in 0..calls { last = unsafe { h.id.send(source, selector, &[]).unwrap() }; }
                let elapsed = unsafe { clock_gettime_nsec_np(16) } - start;
                match name {
                    "integer" => assert_eq!(q.word_bits(q.call(integer, b"wordOf:", &[last]).unwrap()).unwrap(), 42),
                    "float" => assert_eq!(q.word_bits(q.call(float, b"bitsOf:", &[last]).unwrap()).unwrap(), 1.25f64.to_bits() as usize),
                    _ => assert_eq!(last, nil),
                }
                println!("{length} {name} {calls} {elapsed}");
            }
        }
    }
}
